import numpy as np
A=np.zeros((10,10),bool); A[:5,:]=1
B=np.array([[x>=9-y for x in range(10)] for y in range(10)])
C=np.array([[x<=y for x in range(10)] for y in range(10)])
D=np.array([[y>=5 and x>=14-y for x in range(10)] for y in range(10)])
ops=[]
for name,M in [('A',A),('B',B),('C',C)]:
    ops += [(name,M),(' '+name.lower(),~M)]
states={np.zeros((10,10),bool):''}
for depth in range(1,8):
    new=dict(states)
    for s,path in states.items():
        for name,M in ops:
            ns=s|M if name.isupper() else s&M
            if ns.tobytes() not in {x.tobytes() for x in new}: new[ns]=path+' '+name
    states=new
    print(depth,len(states), any(np.array_equal(s,D) for s in states))
    for s,p in states.items():
        if np.array_equal(s,D): print(p);raise SystemExit

